<?php
declare(strict_types=1);
session_start();require_once __DIR__.'/../../src/db.php';require_once __DIR__.'/../../config.php';
if(!($_SESSION['admin']??false)){http_response_code(403);exit('Forbidden');}
$db=db();$db->exec("CREATE TABLE IF NOT EXISTS panorama_3d_objects(id INTEGER PRIMARY KEY AUTOINCREMENT,panorama_id INTEGER NOT NULL,name TEXT NOT NULL,file_url TEXT NOT NULL,format TEXT NOT NULL,settings TEXT NOT NULL DEFAULT '{}',sort_order INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(panorama_id) REFERENCES panoramas(id) ON DELETE CASCADE)");
$id=(int)($_GET['id']??$_POST['panorama_id']??0);$q=$db->prepare('SELECT id,title FROM panoramas WHERE id=?');$q->execute([$id]);$panorama=$q->fetch();if(!$panorama){http_response_code(404);exit('Панорама не найдена');}
if(!isset($_SESSION['panorama_save_csrf']))$_SESSION['panorama_save_csrf']=bin2hex(random_bytes(32));
 
$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!hash_equals($_SESSION['panorama_save_csrf'],(string)($_POST['csrf_token']??'')))throw new RuntimeException('Сессия устарела.');
  $action=(string)($_POST['action']??'');
  if($action==='upload'){
   $f=$_FILES['model']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Выберите STL или GLB.');
   if($f['size']>50*1024*1024)throw new RuntimeException('Максимальный размер модели — 50 МБ.');
   $ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['stl','glb'],true))throw new RuntimeException('Поддерживаются только STL и GLB.');
   $head=file_get_contents($f['tmp_name'],false,null,0,4);if($ext==='glb'&&$head!=="glTF")throw new RuntimeException('Файл GLB имеет неверную сигнатуру.');
   $dir=__DIR__.'/../uploads/objects';if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Не удалось создать каталог моделей.');
   $filename=bin2hex(random_bytes(16)).'.'.$ext;$dest=$dir.'/'.$filename;if(!move_uploaded_file($f['tmp_name'],$dest))throw new RuntimeException('Не удалось сохранить модель.');
   $settings=['distance'=>max(2,min(250,(float)($_POST['distance']??24))),'x'=>max(-100,min(100,(float)($_POST['x']??0))),'y'=>max(-100,min(100,(float)($_POST['y']??0))),'scale'=>max(.001,min(100,(float)($_POST['scale']??1))),'rotX'=>0,'rotY'=>0,'rotZ'=>0,'spin'=>isset($_POST['spin']),'spinX'=>0,'spinY'=>.35,'spinZ'=>0,'style'=>in_array($_POST['style']??'standard',['standard','metal','glass','glow','hologram','wire'],true)?$_POST['style']:'standard','visible'=>true];
   $st=$db->prepare('INSERT INTO panorama_3d_objects(panorama_id,name,file_url,format,settings) VALUES(?,?,?,?,?)');$st->execute([$id,trim($_POST['name']?:pathinfo($f['name'],PATHINFO_FILENAME)),'/uploads/objects/'.$filename,$ext,json_encode($settings,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$msg='Модель загружена.';
  }elseif($action==='save'){
   $obj=(int)($_POST['object_id']??0);$settings=['distance'=>max(2,min(250,(float)($_POST['distance']??24))),'x'=>max(-100,min(100,(float)($_POST['x']??0))),'y'=>max(-100,min(100,(float)($_POST['y']??0))),'scale'=>max(.001,min(100,(float)($_POST['scale']??1))),'rotX'=>max(-360,min(360,(float)($_POST['rotX']??0))),'rotY'=>max(-360,min(360,(float)($_POST['rotY']??0))),'rotZ'=>max(-360,min(360,(float)($_POST['rotZ']??0))),'spin'=>isset($_POST['spin']),'spinX'=>(float)($_POST['spinX']??0),'spinY'=>(float)($_POST['spinY']??.35),'spinZ'=>(float)($_POST['spinZ']??0),'style'=>in_array($_POST['style']??'standard',['standard','metal','glass','glow','hologram','wire'],true)?$_POST['style']:'standard','visible'=>isset($_POST['visible'])];
   $st=$db->prepare('UPDATE panorama_3d_objects SET name=?,settings=? WHERE id=? AND panorama_id=?');$st->execute([trim($_POST['name']),json_encode($settings,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$obj,$id]);$msg='Настройки модели сохранены.';
  }elseif($action==='delete'){
   $obj=(int)($_POST['object_id']??0);$st=$db->prepare('SELECT file_url FROM panorama_3d_objects WHERE id=? AND panorama_id=?');$st->execute([$obj,$id]);$file=$st->fetchColumn();$db->prepare('DELETE FROM panorama_3d_objects WHERE id=? AND panorama_id=?')->execute([$obj,$id]);if($file){$path=__DIR__.'/..'.$file;if(str_starts_with($file,'/uploads/objects/')&&is_file($path)&&!is_link($path))@unlink($path);}$msg='Модель удалена.';
  }
 }catch(Throwable $e){$error=$e->getMessage();}
}
$st=$db->prepare('SELECT * FROM panorama_3d_objects WHERE panorama_id=? ORDER BY sort_order,id');$st->execute([$id]);$objects=$st->fetchAll();
