.wrap{max-width:1100px;margin:auto;padding:24px}.panel{background:#17212b;border:1px solid #344454;border-radius:14px;padding:18px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}label{display:flex;flex-direction:column;gap:6px;color:#cbd5e1}input,select{padding:10px;border-radius:8px;background:#0d1720;color:white;border:1px solid #46596a}.actions{display:flex;gap:10px;align-items:center;margin-top:14px;flex-wrap:wrap}.btn{padding:10px 16px;border:0;border-radius:9px;background:#2685a8;color:white;cursor:pointer}.danger{background:#9b3945}.hint{color:#9aabbc;font-size:13px}.preview{height:170px;display:grid;place-items:center;background:#0a1118;border-radius:10px;font-size:52px}.object-editor{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(230px,1fr);gap:16px;margin:12px 0}.object-stage{position:relative;min-height:300px;background:#07131e;border:1px solid #36516a;border-radius:12px;overflow:hidden;touch-action:none}.object-stage canvas{display:block;width:100%;height:300px;touch-action:none}.stage-help{position:absolute;left:10px;right:10px;bottom:9px;padding:7px 10px;background:#07131edc;border-radius:8px;color:#c7e4f4;font-size:12px;pointer-events:none}.stage-top{position:absolute;top:9px;left:10px;padding:6px 9px;background:#07131edc;border-radius:7px;color:#9ceaff;font-size:12px;pointer-events:none}.placement-controls{display:grid;grid-template-columns:1fr 1fr;gap:9px;align-content:start}.placement-controls label{font-size:12px}.placement-controls input[type=range]{padding:0;width:100%;accent-color:#39bde5}.value-readout{font-variant-numeric:tabular-nums;color:#8fe5ff}.editor-actions{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.subheading{color:#8fe5ff;font-size:14px;margin:0 0 8px}@media(max-width:760px){.object-editor{grid-template-columns:1fr}.object-stage canvas{height:250px}.object-stage{min-height:250px}}.check{flex-direction:row;align-items:center}.msg{padding:12px;background:#16432d;border-radius:8px}.err{padding:12px;background:#55252d;border-radius:8px}
</style></head><body><main class="wrap"><a href="/admin/panorama.php?id=<?=$id?>">← Назад к панораме</a><h1>3D-объекты</h1><p><?=htmlspecialchars($panorama['title'])?> — модели отображаются перед камерой и поворачиваются вместе с направлением взгляда.</p><?php if($msg):?><p class="msg"><?=htmlspecialchars($msg)?></p><?php endif;?><?php if($error):?><p class="err"><?=htmlspecialchars($error)?></p><?php endif;?>
<section class="panel"><h2>Загрузить модель</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['panorama_save_csrf'])?>"><input type="hidden" name="panorama_id" value="<?=$id?>"><input type="hidden" name="action" value="upload"><div class="grid"><label>Файл STL или GLB<input type="file" name="model" accept=".stl,.glb,model/gltf-binary" required></label><label>Название<input name="name" placeholder="Модель планеты"></label><label>Расстояние от камеры<input type="number" name="distance" min="2" max="250" value="24" step=".5"></label><label>Смещение X<input type="number" name="x" value="0" step=".1"></label><label>Высота Y<input type="number" name="y" value="0" step=".1"></label><label>Масштаб<input type="number" name="scale" min=".001" max="100" value="1" step=".1"></label><label>Материал<select name="style"><option value="standard">Обычный</option><option value="metal">Металл</option><option value="glass">Стекло</option><option value="glow">Свечение</option><option value="hologram">Голограмма</option><option value="wire">Каркас</option></select></label><label class="check"><input type="checkbox" name="spin" checked> Автовращение</label></div><p class="hint">GLB: геометрия и базовые PBR-материалы. STL: геометрия с автоматически созданным материалом.</p><div class="actions"><button class="btn">Загрузить 3D-модель</button></div></form></section>
