<canvas aria-label="Интерактивное размещение 3D-модели"></canvas><div class="stage-top">ВИД ОТ КАМЕРЫ · 3D-ПРЕДПРОСМОТР</div><div class="stage-help">Перетаскивай модель мышью или пальцем — X/Y. Колесо мыши — ближе/дальше. Поворот меняй справа.</div>
</div><div><h4 class="subheading">Положение в сцене</h4><div class="placement-controls">
<?php foreach(['x'=>['Горизонталь X',-100,100,.1],'y'=>['Высота Y',-100,100,.1],'distance'=>['Расстояние от камеры',2,250,.5],'scale'=>['Размер модели',.001,100,.1],'rotX'=>['Наклон X°',-180,180,1],'rotY'=>['Поворот Y°',-180,180,1],'rotZ'=>['Наклон Z°',-180,180,1]] as $k=>$cfg):?><label><?=$cfg[0]?><input type="range" data-live-control="<?=$k?>" min="<?=$cfg[1]?>" max="<?=$cfg[2]?>" step="<?=$cfg[3]?>" value="<?=htmlspecialchars((string)($v[$k]??(['distance'=>24,'scale'=>1][$k]??0)))?>"><span class="value-readout" data-live-value="<?=$k?>"></span></label><?php endforeach;?>
</div><div class="editor-actions"><button type="button" class="btn" data-center-model>Вернуть в центр</button><button type="button" class="btn" data-reset-view>Сбросить вид</button></div><p class="hint" data-stage-status>Загрузка 3D-предпросмотра…</p></div></div>
<form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['panorama_save_csrf'])?>"><input type="hidden" name="panorama_id" value="<?=$id?>"><input type="hidden" name="object_id" value="<?=(int)$o['id']?>"><input type="hidden" name="action" value="save"><div class="grid"><label>Название<input name="name" value="<?=htmlspecialchars($o['name'])?>"></label><?php foreach(['distance'=>'Расстояние','x'=>'Смещение X','y'=>'Высота Y','scale'=>'Масштаб','rotX'=>'Поворот X°','rotY'=>'Поворот Y°','rotZ'=>'Поворот Z°','spinX'=>'Скорость X','spinY'=>'Скорость Y','spinZ'=>'Скорость Z'] as $k=>$label):?><label><?=$label?><input type="number" step="any" name="<?=$k?>" value="<?=htmlspecialchars((string)($v[$k]??(['distance'=>24,'scale'=>1,'spinY'=>.35][$k]??0)))?>"></label><?php endforeach;?><label>Визуальный эффект<select name="style"><?php foreach(['standard'=>'Обычный','metal'=>'Металл','glass'=>'Стекло','glow'=>'Свечение','hologram'=>'Голограмма','wire'=>'Каркас'] as $k=>$label):?><option value="<?=$k?>" <?=($v['style']??'standard')===$k?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label class="check"><input type="checkbox" name="spin" <?=!empty($v['spin'])?'checked':''?>> Вращать автоматически</label><label class="check"><input type="checkbox" name="visible" <?=($v['visible']??true)?'checked':''?>> Показывать</label></div><div class="actions"><button class="btn">Сохранить параметры</button></div></form><form method="post" onsubmit="return confirm('Удалить модель?')"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['panorama_save_csrf'])?>"><input type="hidden" name="panorama_id" value="<?=$id?>"><input type="hidden" name="object_id" value="<?=(int)$o['id']?>"><input type="hidden" name="action" value="delete"><button class="btn danger">Удалить модель</button></form></section><?php endforeach;?>
